# Motherboard compatibility checker
# Board: ASUS ROG Crosshair X670E Hero
BOARD = {'socket': 'AM5', 'chipset': 'X670E', 'ddr': 'DDR5'}
def cpu_fits(cpu_socket):
    return cpu_socket == BOARD['socket']
def ram_fits(ram_ddr):
    return ram_ddr == BOARD['ddr']
checks = [
    ('CPU socket matches board', cpu_fits('AM5')),
    ('RAM generation matches board', ram_fits('DDR5')),
]
for label, ok in checks:
    print(('PASS' if ok else 'FAIL') + ' - ' + label)
print('Rule: CPU socket must match exactly; DDR generation must match exactly.')

